from pathlib import Path
import json
p=Path("evidence/external")
data=json.loads("{\"source\":{\"source_id\":\"SRC-037\",\"title\":\"AI Maturity Assessment - SEP 2026\",\"file\":\"assessement - IA no RH.xlsx\",\"format\":\"xlsx_with_screenshots\",\"length\":7,\"unit\":\"captured_pages\",\"published\":null,\"visible_assessment_title_date\":\"SEP 2026\",\"kind\":\"enterprise_ai_maturity_assessment\",\"status\":\"primary_external_source_in_user_provided_capture\",\"extraction\":\"full_visual_transcription_of_available_images\",\"transcription\":\"evidence/external/GARTNER_AI_MATURITY_ASSESSMENT_TRANSCRICAO.md\",\"limitations\":\"Sete capturas das páginas 1–7 de 8; Planilha8 vazia. Título e instruções enterprise, sem HR no título visível. Sem respostas, critérios detalhados de níveis, resultado ou fórmula de agregação.\",\"duplicate_of\":null},\"units\":[{\"id\":\"KU-122\",\"type\":\"assessment_dimension\",\"statement\":\"O assessment apresenta a dimensão AI Strategy: Desenvolver e executar a estratégia de IA, com 5 atividades visíveis.\",\"context\":\"Tradução/síntese do formulário; não é resultado de avaliação da Vivo.\",\"themes\":[\"maturity\",\"assessment\"],\"scope\":[\"enterprise_workforce\"],\"evidence\":\"gartner_assessment_screenshot\",\"sources\":[{\"source_id\":\"SRC-037\",\"locator\":\"Planilha1 / Page 1 of 8 / ASM-01–05\"}]},{\"id\":\"KU-123\",\"type\":\"assessment_dimension\",\"statement\":\"O assessment apresenta a dimensão AI Value: Gerenciar casos de uso e portfólios de IA, com 3 atividades visíveis.\",\"context\":\"Tradução/síntese do formulário; não é resultado de avaliação da Vivo.\",\"themes\":[\"maturity\",\"assessment\"],\"scope\":[\"enterprise_workforce\"],\"evidence\":\"gartner_assessment_screenshot\",\"sources\":[{\"source_id\":\"SRC-037\",\"locator\":\"Planilha2 / Page 2 of 8 / ASM-06–08\"}]},{\"id\":\"KU-124\",\"type\":\"assessment_dimension\",\"statement\":\"O assessment apresenta a dimensão AI Organization: Evoluir ecossistema e modelos operacionais de IA, com 3 atividades visíveis.\",\"context\":\"Tradução/síntese do formulário; não é resultado de avaliação da Vivo.\",\"themes\":[\"maturity\",\"assessment\"],\"scope\":[\"enterprise_workforce\"],\"evidence\":\"gartner_assessment_screenshot\",\"sources\":[{\"source_id\":\"SRC-037\",\"locator\":\"Planilha3 / Page 3 of 8 / ASM-09–11\"}]},{\"id\":\"KU-125\",\"type\":\"assessment_dimension\",\"statement\":\"O assessment apresenta a dimensão AI People and Culture: Desenvolver conhecimento e cultura de IA, com 3 atividades visíveis.\",\"context\":\"Tradução/síntese do formulário; não é resultado de avaliação da Vivo.\",\"themes\":[\"maturity\",\"assessment\"],\"scope\":[\"enterprise_workforce\"],\"evidence\":\"gartner_assessment_screenshot\",\"sources\":[{\"source_id\":\"SRC-037\",\"locator\":\"Planilha4 / Page 4 of 8 / ASM-12–14\"}]},{\"id\":\"KU-126\",\"type\":\"assessment_dimension\",\"statement\":\"O assessment apresenta a dimensão AI Governance: Governar IA e gerenciar riscos, com 3 atividades visíveis.\",\"context\":\"Tradução/síntese do formulário; não é resultado de avaliação da Vivo.\",\"themes\":[\"maturity\",\"assessment\"],\"scope\":[\"enterprise_workforce\"],\"evidence\":\"gartner_assessment_screenshot\",\"sources\":[{\"source_id\":\"SRC-037\",\"locator\":\"Planilha5 / Page 5 of 8 / ASM-15–17\"}]},{\"id\":\"KU-127\",\"type\":\"assessment_dimension\",\"statement\":\"O assessment apresenta a dimensão AI Engineering: Desenvolver e operar sistemas e plataformas de IA, com 5 atividades visíveis.\",\"context\":\"Tradução/síntese do formulário; não é resultado de avaliação da Vivo.\",\"themes\":[\"maturity\",\"assessment\"],\"scope\":[\"enterprise_workforce\"],\"evidence\":\"gartner_assessment_screenshot\",\"sources\":[{\"source_id\":\"SRC-037\",\"locator\":\"Planilha6 / Page 6 of 8 / ASM-18–22\"}]},{\"id\":\"KU-128\",\"type\":\"assessment_dimension\",\"statement\":\"O assessment apresenta a dimensão AI Data: Preparar e gerenciar dados para IA, com 3 atividades visíveis.\",\"context\":\"Tradução/síntese do formulário; não é resultado de avaliação da Vivo.\",\"themes\":[\"maturity\",\"assessment\"],\"scope\":[\"enterprise_workforce\"],\"evidence\":\"gartner_assessment_screenshot\",\"sources\":[{\"source_id\":\"SRC-037\",\"locator\":\"Planilha7 / Page 7 of 8 / ASM-23–25\"}]},{\"id\":\"KU-129\",\"type\":\"assessment_scale\",\"statement\":\"Cada atividade é avaliada por maturidade atual, maturidade desejada em 12 meses e importância; as escalas vão de 1 a 5.\",\"context\":\"Maturidade: não existe, existe parcialmente, existe plenamente, plenamente e otimizada, plenamente e adaptativa. Importância: não importante até da maior importância. Tradução de apoio não oficial.\",\"themes\":[\"maturity\"],\"scope\":[\"enterprise_workforce\"],\"evidence\":\"gartner_assessment_screenshot\",\"sources\":[{\"source_id\":\"SRC-037\",\"locator\":\"instruções e escalas nas Planilhas1–7\"}]},{\"id\":\"KU-130\",\"type\":\"evidence_limitation\",\"statement\":\"O arquivo possui sete capturas com 25 atividades; a oitava aba está vazia. Não há respostas marcadas nem fórmula de agregação visível.\",\"context\":\"O 0% do cabeçalho não é nota de maturidade. A página de resultados não está disponível.\",\"themes\":[\"maturity\",\"source_quality\"],\"scope\":[\"enterprise_workforce\"],\"evidence\":\"source_inspection\",\"sources\":[{\"source_id\":\"SRC-037\",\"locator\":\"Planilhas1–8; imagens e XML do XLSX\"}]},{\"id\":\"KU-131\",\"type\":\"assessment_instruction\",\"statement\":\"O formulário orienta deixar em branco as atividades não relevantes à empresa.\",\"context\":\"Não há regra visível para não sei/não avaliado; estados internos de preparação precisam ser diferenciados de não aplicabilidade.\",\"themes\":[\"maturity\"],\"scope\":[\"enterprise_workforce\"],\"evidence\":\"gartner_assessment_screenshot\",\"sources\":[{\"source_id\":\"SRC-037\",\"locator\":\"instruções nas Planilhas1–7\"}]}]}")
for fname,new,key in [("CORPUS_MANIFEST.jsonl",[data["source"]],"source_id"),("KNOWLEDGE_BASE.jsonl",data["units"],"id")]:
    file=p/fname
    old=[json.loads(x) for x in file.read_text(encoding="utf-8-sig").splitlines() if x.strip()]
    ids={x[key] for x in old}
    for x in new:
        if x[key] in ids:
            assert next(v for v in old if v[key]==x[key])==x, "ID ocupado com conteúdo diferente"
        else: old.append(x)
    file.write_text("".join(json.dumps(x,ensure_ascii=False)+"\n" for x in old),encoding="utf-8")
print("Assessment catalogado: SRC-037; KU-122 a KU-131.")

